import {describe, it, expect} from 'vitest';
import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const sessionWith = (content: string): ChatSession => ({
  sessionId: 'test-session',
  userId: 'user-1',
  entries: [{role: 'user', content, timestamp: new Date().toISOString()}],
});

const rejectingWith = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

describe('ChatOrchestrator non-Error rejections facet', () => {
  it('coerces a string rejection to an Error and calls onError', async () => {
    let capturedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        capturedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith('string boom'), promptBuilder, undefined, {hooks});

    try {
      await orchestrator.processMessage(sessionWith('hello'));
    } catch (e) {
      // expected
    }

    expect(capturedError).toBeInstanceOf(Error);
    expect(capturedError?.message).toBe('string boom');
    expect(capturedError?.cause).toBe('string boom');
  });

  it('coerces a plain object rejection to an Error and calls onError', async () => {
    let capturedError: Error | undefined;
    const reason = {code: 503, detail: 'upstream down'};
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        capturedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {hooks});

    try {
      await orchestrator.processMessage(sessionWith('hello'));
    } catch (e) {
      // expected
    }

    expect(capturedError).toBeInstanceOf(Error);
    expect(capturedError?.message).toMatch(/upstream down/);
    expect(capturedError?.cause).toBe(reason);
  });

  it('passes an Error instance through unchanged to onError', async () => {
    let capturedError: Error | undefined;
    const originalError = new Error('original boom');
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        capturedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith(originalError), promptBuilder, undefined, {hooks});

    try {
      await orchestrator.processMessage(sessionWith('hello'));
    } catch (e) {
      // expected
    }

    expect(capturedError).toBe(originalError);
  });
});

